        sb.append(doc.getNights()).append(doc.getNights() == 1 ? " diária" : " diárias").append("\n");
        sb.append("Diárias: ").append(MoneyUtils.formatBRL(doc.getSubtotal())).append("\n");
        if (doc.getDiscount() != null && doc.getDiscount() > 0) {
