package br.com.pousadamareal.service;

import br.com.pousadamareal.domain.Document;
import br.com.pousadamareal.domain.RatePlan;
import br.com.pousadamareal.domain.Reservation;
import br.com.pousadamareal.domain.ReservationStatus;
import br.com.pousadamareal.repository.RoomRepository;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.sql.SQLException;
import java.time.LocalDate;

import static org.junit.jupiter.api.Assertions.*;

class DocumentServiceTest {
    private DocumentService documentService;
    private RoomRepository roomRepository;

    @BeforeEach
    void setUp() {
        roomRepository = new RoomRepository();
        documentService = new DocumentService(roomRepository);
    }

    @Test
    void testCPFComprovante() throws SQLException {
        Reservation res = createReservation(201, "Carla Dias", "carla@example.com",
                "111.222.333-44", null, null, null, null);
        res.setId(7L);

        Document doc = documentService.generateDocument(res);

        assertEquals("Comprovante de reserva", doc.getTitle());
        assertEquals(7L, doc.getReservationId());
        assertEquals("Carla Dias", doc.getGuestName());
        assertEquals("111.222.333-44", doc.getGuestCpf());
        assertNull(doc.getCompanyCnpj());
        assertNull(doc.getGuestPassport());
        assertTrue(doc.getText().contains("Comprovante de reserva nº 7"));
        assertTrue(doc.getText().contains("Hóspede: Carla Dias (CPF 111.222.333-44)"));
    }

    @Test
    void testCNPJFatura() throws SQLException {
        Reservation res = createReservation(201, "Ana Souza", "ana@example.com",
                null, "12.345.678/0001-90", "Tecnosul Ltda", null, null);
        res.setId(3L);

        Document doc = documentService.generateDocument(res);

        assertEquals("Fatura de hospedagem", doc.getTitle());
        assertEquals(3L, doc.getReservationId());
        assertEquals("Ana Souza", doc.getGuestName());
        assertEquals("12.345.678/0001-90", doc.getCompanyCnpj());
        assertEquals("Tecnosul Ltda", doc.getCompanyName());
        assertNull(doc.getGuestCpf());
        assertNull(doc.getGuestPassport());
        assertTrue(doc.getText().contains("Fatura de hospedagem nº 3"));
        assertTrue(doc.getText().contains("Empresa: Tecnosul Ltda (CNPJ 12.345.678/0001-90)"));
        assertTrue(doc.getText().contains("ISS retido (5%):"));
    }

    @Test
    void testPassportBookingReceipt() throws SQLException {
        Reservation res = createReservation(201, "John Smith", "john@example.com",
                null, null, null, "X1234567", "United Kingdom");
        res.setId(4L);

        Document doc = documentService.generateDocument(res);

        assertEquals("Booking receipt", doc.getTitle());
        assertEquals(4L, doc.getReservationId());
        assertEquals("John Smith", doc.getGuestName());
        assertEquals("X1234567", doc.getGuestPassport());
        assertEquals("United Kingdom", doc.getGuestCountry());
        assertNull(doc.getGuestCpf());
        assertNull(doc.getCompanyCnpj());
        assertTrue(doc.getText().contains("Booking receipt no. 4"));
        assertTrue(doc.getText().contains("Guest: John Smith (passport X1234567, United Kingdom)"));
        assertTrue(doc.getText().contains("BRL"));
    }

    private Reservation createReservation(int roomNumber, String name, String email,
                                         String cpf, String cnpj, String companyName,
                                         String passport, String country) {
        Reservation res = new Reservation();
        res.setRoomNumber(roomNumber);
        res.setGuestName(name);
        res.setGuestEmail(email);
        res.setGuestCpf(cpf);
        res.setCompanyCnpj(cnpj);
        res.setCompanyName(companyName);
        res.setGuestPassport(passport);
        res.setGuestCountry(country);
        res.setCheckIn(LocalDate.of(2027, 3, 10));
        res.setCheckOut(LocalDate.of(2027, 3, 12));
        res.setGuests(2);
        res.setRatePlan(RatePlan.STANDARD);
        res.setNights(2);
        res.setSubtotal(779.80);
        res.setDiscount(0);
        res.setTotal(779.80);
        res.setStatus(ReservationStatus.CONFIRMED);
        res.setAmountPaid(779.80);
        return res;
    }
}

